x ← 15

IF(x > 10)
{
   IF(x > 20)
   {
      DISPLAY "very large"
   }
   ELSE
   {
      DISPLAY "medium"
   }
}
ELSE
{
   DISPLAY "small"
}

-- Trace:
-- Step 1: outer condition (x > 10) = (15 > 10) = true → enter outer IF
-- Step 2: inner condition (x > 20) = (15 > 20) = false → enter inner ELSE
-- Output: medium

-- IMPORTANT: if outer had been false, the inner IF/ELSE
-- would NEVER be evaluated at all

score ← 75

IF(score ≥ 90)
{
   DISPLAY "A"
}
ELSE
{
   IF(score ≥ 80)
   {
      DISPLAY "B"
   }
   ELSE
   {
      IF(score ≥ 70)
      {
         DISPLAY "C"
      }
      ELSE
      {
         DISPLAY "F"
      }
   }
}

-- Trace for score = 75:
-- (score ≥ 90) = false → outer ELSE
-- (score ≥ 80) = false → middle ELSE
-- (score ≥ 70) = true  → displays "C"
-- Output: C

-- These produce the same output for the 'in range' case
-- but the nested version can handle MORE cases:

-- Nested version (3 distinct outcomes):
x ← 5
IF(x > 0)
{
   IF(x < 10)
   {
      DISPLAY "in range"     -- x is 1-9
   }
   ELSE
   {
      DISPLAY "too big"      -- x is 10 or more
   }
}
ELSE
{
   DISPLAY "not positive"    -- x is 0 or negative
}

-- AND version (only one outcome actionable):
IF((x > 0) AND (x < 10))
{
   DISPLAY "in range"        -- x is 1-9
}
-- Does nothing for x <= 0 or x >= 10 unless you add ELSE

x ← 3
y ← 7

IF(x > 5)
{
   IF(y > 5)
   {
      DISPLAY "both big"
   }
   ELSE
   {
      DISPLAY "only x is big"
   }
}
ELSE
{
   IF(y > 5)
   {
      DISPLAY "only y is big"
   }
   ELSE
   {
      DISPLAY "neither is big"
   }
}

-- Step 1: outer (x > 5) = (3 > 5) = false → outer ELSE
-- Step 2: in outer ELSE, check (y > 5) = (7 > 5) = true
-- Step 3: inner IF in ELSE branch executes
-- Output: only y is big
-- Note: the IF block inside the outer IF is NEVER evaluated

temp ← 72
humidity ← 80

IF(temp ≥ 80)
{
   IF(humidity ≥ 70)
   {
      DISPLAY "hot and humid"
   }
   ELSE
   {
      DISPLAY "hot and dry"
   }
}
ELSE
{
   IF(temp ≥ 60)
   {
      IF(humidity ≥ 70)
      {
         DISPLAY "comfortable but humid"
      }
      ELSE
      {
         DISPLAY "comfortable and dry"
      }
   }
   ELSE
   {
      DISPLAY "cold"
   }
}

-- Trace for temp=72, humidity=80:
-- (temp ≥ 80) = (72 ≥ 80) = false → outer ELSE
-- (temp ≥ 60) = (72 ≥ 60) = true  → middle IF
-- (humidity ≥ 70) = (80 ≥ 70) = true → innermost IF
-- Output: comfortable but humid
